"""Search a 2D Matrix II — staircase search from the top-right.

At the top-right corner, moving left strictly decreases and moving down strictly
increases, so each step eliminates a whole row or column.

Time: O(m + n)   Space: O(1)
"""
from typing import List


class Solution:
    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:
        if not matrix or not matrix[0]:
            return False
        row, col = 0, len(matrix[0]) - 1
        while row < len(matrix) and col >= 0:
            value = matrix[row][col]
            if value == target:
                return True
            if value > target:
                col -= 1
            else:
                row += 1
        return False
